def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive_opponents = []
    prev_bids = []
    aggressive_bids = []
    urgent_opponents = 0

    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append(opp)
            if opp.get('hp', 10) <= 3 or opp.get('no_water_days', 0) >= 2:
                urgent_opponents += 1
            prev = opp.get('previous_trace', {})
            if prev:
                bid = prev.get('bid')
                if bid is not None:
                    prev_bids.append(float(bid))
                    if bid >= 90:
                        aggressive_bids.append(float(bid))

    if not alive_opponents:
        return float(min(budget, 18.0))

    scarcity = (MAX_SUPPLY - supply) / float(MAX_SUPPLY - MIN_SUPPLY)
    scarcity = max(0.0, min(1.0, scarcity))

    if prev_bids:
        high_prev = max(prev_bids)
        avg_prev = sum(prev_bids) / len(prev_bids)
    else:
        high_prev = 0.0
        avg_prev = 0.0

    emergency = hp <= 2 or no_water_days >= 2
    stressed = hp <= 4 or no_water_days >= 1

    if emergency:
        target = max(88.0, min(126.0, high_prev + 4.0))
        if supply <= 17:
            target = max(target, 108.0)
        return float(min(budget, target))

    if stressed:
        target = 58.0 + 28.0 * scarcity + 6.0 * urgent_opponents
        if high_prev > 0:
            target = max(target, min(118.0, high_prev + 2.5))
        return float(min(budget, target))

    target = 28.0 + 20.0 * scarcity

    if supply <= 17:
        target += 14.0
    elif supply >= 22:
        target -= 6.0

    if aggressive_bids:
        target = max(target, min(92.0, avg_prev * 0.72 + 3.0))
    elif high_prev > 0:
        target = max(target, min(70.0, avg_prev * 0.6 + 2.0))

    if urgent_opponents >= 2:
        target += 8.0
    elif urgent_opponents == 0:
        target -= 4.0

    if day >= 8 and hp >= 7:
        target -= 5.0

    reserve_floor = DAILY_SALARY * max(0, 10 - int(day)) * 0.18
    affordable = budget
    if budget > reserve_floor:
        affordable = budget - reserve_floor * 0.15

    bid = min(affordable, target)
    bid = max(0.0, min(budget, bid))
    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])

    alive_opps = []
    for oid, o in opponents_status.items():
        if o.get('alive', False):
            alive_opps.append((oid, o))

    if not alive_opps:
        return min(my_status['budget'], DAILY_SALARY * 0.4)

    # Inspect yesterday bids for immediate reaction
    yesterday_bids = []
    yesterday_hp = []
    for oid, o in alive_opps:
        prev = o.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            try:
                b = float(prev.get('bid'))
            except Exception:
                b = None
            if b is not None:
                yesterday_bids.append(b)
                yesterday_hp.append(float(prev.get('hp_after', o.get('hp', 0))))

    highest_prev_bid = max(yesterday_bids) if yesterday_bids else 0.0
    avg_prev_bid = sum(yesterday_bids) / float(len(yesterday_bids)) if yesterday_bids else 0.0

    # Determine how many water units are likely available today
    # (Used only to scale conservatively)
    expected_units = int(supply / float(WATER_REQ)) if WATER_REQ > 0 else 0
    # If supply is enough for at least one full unit, we can bid less aggressively.

    hp = float(my_status['hp'])
    budget = float(my_status['budget'])
    no_water_days = int(my_status.get('no_water_days', 0))

    # Aggression control:
    # If someone bid extremely high yesterday, assume they will continue; bid just enough to compete.
    # Cindy showed very high bids, so we avoid matching her ceiling but stay competitive.
    if highest_prev_bid >= DAILY_SALARY * 1.1:
        # Competitive but budget-aware
        if hp <= 2 or no_water_days >= 2:
            bid = DAILY_SALARY * 0.9
        else:
            bid = max(DAILY_SALARY * 0.55, min(DAILY_SALARY * 0.75, highest_prev_bid * 0.55))
    elif highest_prev_bid >= DAILY_SALARY * 0.6:
        if hp <= 2 or no_water_days >= 2:
            bid = DAILY_SALARY * 0.75
        else:
            bid = max(DAILY_SALARY * 0.45, highest_prev_bid * 0.5)
    else:
        # Low pressure yesterday: bid around a moderate baseline
        if hp <= 2:
            bid = DAILY_SALARY * 0.85
        elif no_water_days >= 2:
            bid = DAILY_SALARY * 0.7
        else:
            bid = DAILY_SALARY * 0.55

    # Scale down if supply likely supports multiple units; scale up slightly if supply is tight.
    if expected_units <= 0:
        bid = min(bid * 0.9, DAILY_SALARY * 0.8)
    elif expected_units == 1:
        bid = min(bid * 1.0, DAILY_SALARY * 0.85)
    else:
        bid = min(bid * 0.85, DAILY_SALARY * 0.75)

    # Ensure we don't overdraw budget
    bid = min(bid, budget)

    # If budget is too low, bid what we can
    if bid < 0:
        bid = 0.0

    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 7
    DAILY_SALARY = 80

    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    if not alive_opponents:
        return min(my_status['budget'], 20.0)

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    if my_status['hp'] <= 3:
        return min(my_status['budget'], DAILY_SALARY * 1.2)

    if yesterday_bids:
        max_prev = max(yesterday_bids)
        if max_prev > DAILY_SALARY:
            return min(my_status['budget'], max_prev * 0.95)
        return min(my_status['budget'], max(DAILY_SALARY * 0.6, max_prev + 5.0))

    return min(my_status['budget'], DAILY_SALARY * 0.7)
